function KERNEL_IS_CONSTANT(G, f):
    m <- max over v of f[v]
    start <- any v with f[v] = m
    level <- {start}; queue <- [start]
    while queue not empty:
        v <- pop(queue)
        for each neighbour u of v:
            if f[u] = m and u not in level:
                add u to level; push u to queue
    return (level = V)

function BN(g, r, d):
    return g - (r+1)*(g - d + r)

function BN_ROW(g, r, d0, length):
    row <- [BN(g, r, d0)]
    repeat length-1 times:
        row.append(row.last + (r+1))
    return row

function SERRE_DUAL(g, r, d):
    return (g, g-1-d+r, 2g-2-d)   # BN invariant under this

